using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class PlaceMusicChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify()=>VerifyWithCapture(null);
 public static void VerifyWithCapture(Action<SharedRhythm,VillagerSocial,CreatureHybrid> capture,Action<SharedRhythm,VillagerSocial,CreatureHybrid> prepare=null,Action<SharedRhythm,VillagerSocial,CreatureHybrid> completed=null){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var instrument=slice.GetComponentInChildren<SharedRhythm>();var prop=instrument.GetComponent<CreatureAffordance>();var people=slice.GetComponentsInChildren<VillagerSocial>();var host=people[0];var nav=god.GetComponent<IslandNavigator>();var site=god.GetComponent<CreatureConstructionLearning>().sites[0];
  var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=field.GetValue(slice);var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var godAt=god.transform.position;var godRotation=god.transform.rotation;var toyAt=prop.transform.position;var toyRotation=prop.transform.rotation;var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused,locked=site.Locked;
  god.Interrupt("Place music QA");foreach(var person in people){person.ResetTask();person.GetComponent<VillagerExploration>().ResetTask();person.GetComponent<VillagerResourceGathering>().Cancel();person.GetComponent<VillagerBlockPlay>().ResetTask();}
  var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,hunger=.1f,water=100,crops=100};test.Hybrid.time=200;field.SetValue(slice,test);slice.GetComponentInChildren<VillageFamilies>().ResetWorld();
  Vector3 anchor=default;
  void Stage(){host.ResetTask();god.Interrupt("Stage place music");instrument.ResetOffer();prop.Item.held=false;prop.host=null;site.Paused=site.Locked=false;test.Hybrid.motivation=new CreatureMotivation();host.Memory.nextInvitationAt=0;host.Memory.trust=.7f;host.Memory.restNeed=.5f;
   Require(nav.world.Sample(site.World(new Vector3(0,0,-28)),nav.profile,8,out var at),"No creature music approach");god.transform.position=nav.world.ProjectFoot(at,nav.profile);nav.ResetRoute();
   for(int i=0;i<people.Length;i++){var route=people[i].GetComponent<IslandNavigator>();Require(nav.world.Sample(site.World(new Vector3(i==0?10:24,0,-12+i*3)),route.profile,5,out at),"No music host stage");people[i].transform.position=nav.world.ProjectFoot(at,route.profile);route.ResetRoute();}
   anchor=site.World(new Vector3(0,.3f,-12));prop.transform.SetPositionAndRotation(anchor,site.transform.rotation);god.transform.LookAt(new Vector3(anchor.x,god.transform.position.y,anchor.z));foreach(var target in god.Targets)if(target.affordance!=null)target.affordance.cooldown=test.Hybrid.time+1000;prop.cooldown=0;Physics.SyncTransforms();
  }
  void Offer(){Require(host.TryShare(prop),"Stationary chime invitation refused");for(int i=0;i<1800&&!host.Ready&&host.Active;i++){test.Hybrid.time+=.05f;host.Tick(.05f,false);Require(!prop.Item.held&&Vector3.Distance(prop.transform.position,anchor)<.001f,"Villager carried away a placed gathering instrument");}Require(host.Ready,"Host did not reach placed instrument");}
  try{
   site.ResetConstruction();Stage();host.Memory.RememberPlace(0,true,0);site.Paused=true;Require(!host.TryShare(prop)&&prop.host==null&&!host.Active,"Paused place started portable fallback");site.Paused=false;Offer();var hostAt=host.transform.position;test.paused=true;host.Tick(10,true);Require(host.Ready&&host.transform.position==hostAt&&prop.transform.position==anchor,"Pause moved stationary invitation");test.paused=false;
   prop.Item.held=true;host.Tick(.05f,false);Require(!host.Active&&prop.host==null&&prop.Item.held&&host.Memory.rhythmGames==0,"Player pickup retained invitation or was undone");prop.Item.held=false;
   Stage();Offer();prop.transform.position+=Vector3.right*nav.world.Scale*2;var moved=prop.transform.position;host.Tick(.05f,false);Require(!host.Active&&prop.host==null&&prop.transform.position==moved,"Moved instrument retained old invitation or snapped back");
   Stage();Offer();int missed=host.Memory.missedInvitations;for(int i=0;i<400&&host.Active;i++){test.Hybrid.time+=.05f;host.Tick(.05f,false);}Require(!host.Active&&host.Memory.missedInvitations==missed+1&&host.Memory.rhythmGames==0&&host.Memory.Place(0).visits==1&&prop.transform.position==anchor,"Unanswered invitation commanded a game or fabricated place progress");
   Stage();Offer();prepare?.Invoke(instrument,host,god);bool captured=false;for(int i=0;i<1800&&host.Memory.rhythmGames==0;i++){god.Tick(.05f);host.Tick(.05f,false);foreach(var person in people){var audience=person.GetComponent<VillagerExploration>();if(audience.MusicAudience)audience.Tick(.05f,false);}if(instrument.Active&&instrument.Beats>=3&&!captured){captured=true;capture?.Invoke(instrument,host,god);}Require(Vector3.Distance(prop.transform.position,anchor)<.001f&&!prop.Item.held,"Performance moved placed instrument");}
   Require(instrument.Beats==8&&host.Memory.rhythmGames==1&&test.WorldPlay.rhythmGames==1&&host.Memory.Place(0).visits==2,"Native place performance did not complete and remember use: "+god.Owner+" / "+god.Explanation);
   completed?.Invoke(instrument,host,god);Require(test.Hybrid.receipt.rhythmGame&&test.Hybrid.receipt.partner==host.GetComponent<HybridTarget>().id&&god.Feedback(true)&&!god.Feedback(true),"Stationary performance lost one-shot contextual teaching");var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.Social(0).Place(0).visits==2&&saved.Social(0).rhythmGames==1,"Place performance save invalid");
   Stage();Offer();for(int i=0;i<1800&&!instrument.Active;i++){god.Tick(.05f);host.Tick(.05f,false);}Require(instrument.Active,"No active place performance to interrupt");int games=host.Memory.rhythmGames;prop.Item.held=true;host.Tick(.05f,false);god.Tick(.05f);Require(!instrument.Active&&!host.Active&&prop.host==null&&prop.Item.held&&host.Memory.rhythmGames==games&&!test.Hybrid.receipt.eligible,"Chime pickup retained active duet or credited incomplete game");prop.Item.held=false;
   Debug.Log("BWVR_PLACE_MUSIC_PASS: native stationary approach/offer, pause, player pickup, moved target and ignored-invitation cleanup, utility-selected eight-beat creature duet, place memory and once-only saved teaching");
  }finally{instrument.Cancel();foreach(var person in people){person.GetComponent<CarryItem>().held=false;person.ResetTask();person.GetComponent<VillagerExploration>().ResetTask();}god.Interrupt("Place music QA complete");field.SetValue(slice,original);site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;site.Locked=locked;for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}god.transform.SetPositionAndRotation(godAt,godRotation);nav.ResetRoute();prop.Item.held=false;prop.host=null;prop.transform.SetPositionAndRotation(toyAt,toyRotation);prop.GetComponent<Collider>().enabled=true;}
 }
}
}
